// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAdminPlans Get configured plans
	// (GET /admin/plans)
	GetAdminPlans(ctx context.Context, request GetAdminPlansRequestObject) (GetAdminPlansResponseObject, error)
	// UpdateAdminPlans Update configured plans
	// (PUT /admin/plans)
	UpdateAdminPlans(ctx context.Context, request UpdateAdminPlansRequestObject) (UpdateAdminPlansResponseObject, error)
	// ListAdminUsers List users
	// (GET /admin/users)
	ListAdminUsers(ctx context.Context, request ListAdminUsersRequestObject) (ListAdminUsersResponseObject, error)
	// UpdateAdminUser Change a user's role or disabled state
	// (PATCH /admin/users/{id})
	UpdateAdminUser(ctx context.Context, request UpdateAdminUserRequestObject) (UpdateAdminUserResponseObject, error)
	// UpdateAdminUserPlan Assign a plan to a user
	// (PUT /admin/users/{id}/plan)
	UpdateAdminUserPlan(ctx context.Context, request UpdateAdminUserPlanRequestObject) (UpdateAdminUserPlanResponseObject, error)
	// GetAuthConfig Get public authentication options
	// (GET /auth/config)
	GetAuthConfig(ctx context.Context, request GetAuthConfigRequestObject) (GetAuthConfigResponseObject, error)
	// Login Log in with email and password
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Log out the current session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Register Register a user
	// (POST /auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// RevokeOtherSessions Revoke every session except the current one
	// (DELETE /auth/sessions)
	RevokeOtherSessions(ctx context.Context, request RevokeOtherSessionsRequestObject) (RevokeOtherSessionsResponseObject, error)
	// FlickrAccountCallback Complete connecting a Flickr account
	// (GET /flickr-accounts/callback)
	FlickrAccountCallback(ctx context.Context, request FlickrAccountCallbackRequestObject) (FlickrAccountCallbackResponseObject, error)
	// ConnectFlickrAccount Start connecting a Flickr account
	// (POST /flickr-accounts/connect)
	ConnectFlickrAccount(ctx context.Context, request ConnectFlickrAccountRequestObject) (ConnectFlickrAccountResponseObject, error)
	// GetHealth Report process health.
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// ListKeys List the current user's API keys
	// (GET /keys)
	ListKeys(ctx context.Context, request ListKeysRequestObject) (ListKeysResponseObject, error)
	// CreateKey Add a Flickr API key
	// (POST /keys)
	CreateKey(ctx context.Context, request CreateKeyRequestObject) (CreateKeyResponseObject, error)
	// DeleteKey Delete an API key
	// (DELETE /keys/{id})
	DeleteKey(ctx context.Context, request DeleteKeyRequestObject) (DeleteKeyResponseObject, error)
	// GetKey Get one API key
	// (GET /keys/{id})
	GetKey(ctx context.Context, request GetKeyRequestObject) (GetKeyResponseObject, error)
	// UpdateKey Change a key's label, limits, or secret
	// (PUT /keys/{id})
	UpdateKey(ctx context.Context, request UpdateKeyRequestObject) (UpdateKeyResponseObject, error)
	// GetMe Get the authenticated user
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// UpdateMe Update the authenticated user's profile
	// (PATCH /me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

